"use client";

import { FormEvent, useEffect, useState } from "react";

type Task = {
  id: string;
  subject: string;
  title: string;
  dueDate: string;
  completed: boolean;
};

const STORAGE_KEY = "student-task-manager:tasks";

function isTask(value: unknown): value is Task {
  if (typeof value !== "object" || value === null) {
    return false;
  }

  const task = value as Record<string, unknown>;

  return (
    typeof task.id === "string" &&
    typeof task.subject === "string" &&
    typeof task.title === "string" &&
    typeof task.dueDate === "string" &&
    typeof task.completed === "boolean"
  );
}

export default function Home() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [subject, setSubject] = useState("");
  const [title, setTitle] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [hasLoadedTasks, setHasLoadedTasks] = useState(false);

  useEffect(() => {
    const savedTasks = window.localStorage.getItem(STORAGE_KEY);
    let loadedTasks: Task[] = [];

    if (savedTasks) {
      try {
        const parsedTasks: unknown = JSON.parse(savedTasks);

        if (Array.isArray(parsedTasks) && parsedTasks.every(isTask)) {
          loadedTasks = parsedTasks;
        }
      } catch {
        window.localStorage.removeItem(STORAGE_KEY);
      }
    }

    const loadTimer = window.setTimeout(() => {
      setTasks(loadedTasks);
      setHasLoadedTasks(true);
    }, 0);

    return () => window.clearTimeout(loadTimer);
  }, []);

  useEffect(() => {
    if (!hasLoadedTasks) {
      return;
    }

    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
  }, [hasLoadedTasks, tasks]);

  function addTask(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!subject.trim() || !title.trim() || !dueDate) {
      return;
    }

    const newTask: Task = {
      id: crypto.randomUUID(),
      subject: subject.trim(),
      title: title.trim(),
      dueDate,
      completed: false,
    };

    setTasks((currentTasks) => [...currentTasks, newTask]);
    setSubject("");
    setTitle("");
    setDueDate("");
  }

  function toggleTask(taskId: string) {
    setTasks((currentTasks) =>
      currentTasks.map((task) =>
        task.id === taskId ? { ...task, completed: !task.completed } : task,
      ),
    );
  }

  function deleteTask(taskId: string) {
    setTasks((currentTasks) => currentTasks.filter((task) => task.id !== taskId));
  }

  return (
    <main>
      <h1>과제 관리</h1>

      <form onSubmit={addTask}>
        <label>
          과목명
          <input
            value={subject}
            onChange={(event) => setSubject(event.target.value)}
            placeholder="예: 웹 프로그래밍"
            required
          />
        </label>
        <label>
          과제명
          <input
            value={title}
            onChange={(event) => setTitle(event.target.value)}
            placeholder="예: 개인 홈페이지 만들기"
            required
          />
        </label>
        <label>
          마감일
          <input
            type="date"
            value={dueDate}
            onChange={(event) => setDueDate(event.target.value)}
            required
          />
        </label>
        <button type="submit">과제 추가</button>
      </form>

      <section aria-labelledby="task-list-heading">
        <h2 id="task-list-heading">과제 목록</h2>
        {tasks.length === 0 ? (
          <p>등록된 과제가 없습니다.</p>
        ) : (
          <ul>
            {tasks.map((task) => (
              <li key={task.id}>
                <label>
                  <input
                    type="checkbox"
                    checked={task.completed}
                    onChange={() => toggleTask(task.id)}
                  />
                  <span className={task.completed ? "completed" : ""}>
                    {task.subject} — {task.title} (마감일: {task.dueDate})
                  </span>
                </label>
                <button type="button" onClick={() => deleteTask(task.id)}>
                  삭제
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>
    </main>
  );
}
